import{_ as t,c as o,a0 as r,o as a}from"./chunks/framework.B6JXc2q-.js";const u=JSON.parse('{"title":"认证后台恢复 singleflight 约束","description":"","frontmatter":{},"headers":[],"relativePath":"spec/auth/auth_recovery_singleflight.md","filePath":"spec/auth/auth_recovery_singleflight.md"}'),c={name:"spec/auth/auth_recovery_singleflight.md"};function d(l,e,i,_,s,h){return a(),o("div",null,e[0]||(e[0]=[r('<h1 id="认证后台恢复-singleflight-约束" tabindex="-1">认证后台恢复 singleflight 约束 <a class="header-anchor" href="#认证后台恢复-singleflight-约束" aria-label="Permalink to &quot;认证后台恢复 singleflight 约束&quot;">​</a></h1><blockquote><p>状态：现行专项约束 最后核对：2026-09-28 实现：<code>xiaomusic/auth.py</code> 的后台 recovery 与 singleflight 方法</p></blockquote><h2 id="_1-范围" tabindex="-1">1. 范围 <a class="header-anchor" href="#_1-范围" aria-label="Permalink to &quot;1. 范围&quot;">​</a></h2><p>本文只约束后台认证恢复任务的并发隔离，不定义认证状态机、token 交换或 runtime commit 语义；后者以 <code>auth_runtime_recovery.md</code> 为准。</p><h2 id="_2-角色" tabindex="-1">2. 角色 <a class="header-anchor" href="#_2-角色" aria-label="Permalink to &quot;2. 角色&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>条件</th><th>行为</th></tr></thead><tbody><tr><td>leader</td><td>在锁内确认无 inflight recovery 且不在 backoff</td><td>独占执行 <code>_schedule_background_recovery()</code> 创建的恢复主链</td></tr><tr><td>follower</td><td>已有 leader</td><td>等待 <code>_recovery_complete_event</code>，不再启动第二条恢复链</td></tr><tr><td>blocked</td><td>recovery backoff 仍有效</td><td>直接跳过本轮恢复</td></tr></tbody></table><h2 id="_3-实现约束" tabindex="-1">3. 实现约束 <a class="header-anchor" href="#_3-实现约束" aria-label="Permalink to &quot;3. 实现约束&quot;">​</a></h2><ol><li><code>_try_acquire_recovery_leader()</code> 只做启动前快速判断，不设置 inflight。</li><li><code>_acquire_recovery_leader_lock()</code> 才能在 <code>_recovery_lock</code> 内设置 <code>_recovery_inflight</code>、leader ctx 并清除完成事件。</li><li>leader 必须在 <code>finally</code> 中调用 <code>_release_recovery_leader()</code>。</li><li>非 <code>ok</code> 结果进入 backoff；已经判定需要人工登录时不再叠加自动 backoff。</li><li><code>_wait_for_recovery_complete()</code> 必须有超时，不能无限等待。</li><li><code>self._recovery_task</code> 由 AuthManager 持有；已有未完成任务时不得重复创建。</li></ol><h2 id="_4-不再适用的旧描述" tabindex="-1">4. 不再适用的旧描述 <a class="header-anchor" href="#_4-不再适用的旧描述" aria-label="Permalink to &quot;4. 不再适用的旧描述&quot;">​</a></h2><p>旧版本把 singleflight 描述为 <code>auth_call</code> 中的 “first suspect → non-destructive recovery → clear short session → rebuild” 链路，并引用 <code>_clear_short_lived_session()</code>、<code>_attempt_non_destructive_auth_recovery()</code> 等方法。当前代码已经移除这些方法，这套阶段模型不再是现行约束。</p><h2 id="_5-验证依据" tabindex="-1">5. 验证依据 <a class="header-anchor" href="#_5-验证依据" aria-label="Permalink to &quot;5. 验证依据&quot;">​</a></h2><ul><li><code>xiaomusic/auth.py</code>：<code>_schedule_background_recovery()</code>、<code>_try_acquire_recovery_leader()</code>、<code>_acquire_recovery_leader_lock()</code>、<code>_release_recovery_leader()</code>、<code>_wait_for_recovery_complete()</code></li><li><code>tests/test_auth_runtime_stability.py</code></li><li><code>tests/unit/test_auth_short_session_rebuild.py</code></li><li><code>tests/unit/test_auth_classification_regression.py</code></li></ul>',12)]))}const f=t(c,[["render",d]]);export{u as __pageData,f as default};
